import unicodedata


def _cw(ch):
    if unicodedata.category(ch) in ('Mn', 'Me', 'Cf'):
        return 0
    if unicodedata.east_asian_width(ch) in ('W', 'F'):
        return 2
    return 1


def fit(text: str, width: int) -> str:
    if sum(_cw(c) for c in text) <= width:
        return text

    budget = width - 1
    clusters = []  # each entry: [string, width]
    for ch in text:
        w = _cw(ch)
        if w == 0 and clusters:
            clusters[-1][0] += ch
        else:
            clusters.append([ch, w])

    out = []
    used = 0
    for s, w in clusters:
        if used + w > budget:
            break
        out.append(s)
        used += w
    return ''.join(out) + '…'
